import{_ as r,o as a,c as i,a2 as e}from"./chunks/framework.CHeM0PsO.js";const s="/images/misskey-explore.webp",l="/images/misskey-timeline.webp",o="/images/misskey-post-form.webp",d="/images/misskey-search.webp",n="/images/misskey-profile.webp",f=JSON.parse('{"title":"帖子与时间线","description":"","frontmatter":{},"headers":[],"relativePath":"guide/posts.md","filePath":"guide/posts.md","lastUpdated":1793076233000}'),p={name:"guide/posts.md"};function h(g,t,m,c,u,b){return a(),i("div",null,[...t[0]||(t[0]=[e('<h1 id="帖子与时间线" tabindex="-1">帖子与时间线 <a class="header-anchor" href="#帖子与时间线" aria-label="Permalink to &quot;帖子与时间线&quot;">​</a></h1><p>帖子是社区的基本内容单元。你可以通过「发现」页浏览社区热门内容，也可以在「时间线」中查看关注的人或整个社区的动态。</p><p>帖子支持文字、文件、投票等内容。发布后，帖子会加入时间轴，你的关注者与服务器用户都可以看到。你可以对帖子做出反应，也可以回复和引用，或将帖子加到我的最爱，方便以后查阅。</p><p>在本站发帖还可以享受（？）来自 Aliya 的锐评。</p><h2 id="发现" tabindex="-1">发现 <a class="header-anchor" href="#发现" aria-label="Permalink to &quot;发现&quot;">​</a></h2><p>发现页是登录后的默认首页，展示社区里的热门内容。</p><ul><li><strong>精选</strong>：展示热门帖子和投票，支持按「推荐」「热度」「最新」排序，无限滚动加载。</li><li><strong>用户</strong>：发现社区活跃用户。</li><li><strong>角色</strong>：浏览服务器角色。</li></ul><p>热度会随时间衰减；推荐模式兼顾热门与新发布的内容。频道中的帖子也会出现在发现页，并标注来源频道。</p><p><img src="'+s+'" alt="发现页"></p><h2 id="时间线" tabindex="-1">时间线 <a class="header-anchor" href="#时间线" aria-label="Permalink to &quot;时间线&quot;">​</a></h2><p>时间线提供多种视角来浏览帖子：</p><table tabindex="0"><thead><tr><th>类型</th><th>看到什么</th></tr></thead><tbody><tr><td>首页</td><td>你关注的人发的帖子</td></tr><tr><td>本地</td><td>本服务器所有人的公开帖子</td></tr><tr><td>社交</td><td>首页 + 本地 合并</td></tr><tr><td>全局</td><td>所有公开帖子（本服务器不联合，内容与本地基本一致）</td></tr><tr><td>列表</td><td>你自建的用户列表</td></tr><tr><td>天线</td><td>按关键词/用户订阅的内容</td></tr><tr><td>频道</td><td>特定频道的内容</td></tr></tbody></table><p>你可以筛选是否显示转帖、回复、仅看带图帖子等。新帖子会实时推送，无需手动刷新。</p><p><img src="'+l+'" alt="时间线"></p><p>列表与天线的用法见<a href="/guide/misskey/lists-antennas">列表与天线</a>，频道详见<a href="/guide/misskey/channels">频道</a>。</p><h2 id="发帖" tabindex="-1">发帖 <a class="header-anchor" href="#发帖" aria-label="Permalink to &quot;发帖&quot;">​</a></h2><p>点击发帖按钮即可发布内容，支持：</p><ul><li><strong>可见性</strong>：公开、仅首页、仅关注者、指定用户</li><li><strong>附件</strong>：图片、视频等文件，可标记为敏感内容</li><li><strong>投票</strong>：创建多选项投票</li><li><strong>内容警告</strong>：折叠正文，仅显示提示文字</li><li><strong>定时发布</strong>：设定未来时间自动发出，同时可排队的数量由服务器策略决定；发出成功或失败都会通知</li><li><strong>草稿</strong>：暂时保存，稍后继续编辑，草稿数量上限由服务器策略决定</li><li><strong>话题标签</strong>：附加 #标签 方便他人发现</li><li><strong>频道投稿</strong>：发布到指定频道</li><li><strong>引用与回复</strong>：引用他人帖子附加评论，或直接在帖子下回复</li></ul><p>帖子正文支持 <a href="/guide/misskey/mfm">MFM 语法</a>，可以实现加粗、动画、配色等富文本效果。</p><p><img src="'+o+'" alt="发帖窗口"></p><h2 id="互动" tabindex="-1">互动 <a class="header-anchor" href="#互动" aria-label="Permalink to &quot;互动&quot;">​</a></h2><p>看到喜欢的帖子，你可以：</p><ul><li><strong>回应</strong>：用 Emoji 表达态度（不只是点赞），详见<a href="/guide/misskey/reactions">回应与表情符号</a></li><li><strong>转帖</strong>：分享到自己的时间线</li><li><strong>引用</strong>：转帖并加上自己的想法</li><li><strong>回复</strong>：参与讨论</li><li><strong>收藏 / 便签</strong>：保存喜欢的内容，详见<a href="/guide/misskey/clips-favorites">便签与收藏</a></li><li><strong>分享 / 举报</strong>：生成链接或向管理员反馈</li></ul><p>帖子右下角「…」菜单还提供：</p><table tabindex="0"><thead><tr><th>菜单项</th><th>说明</th></tr></thead><tbody><tr><td>翻译</td><td>翻译帖子正文（需服务器或浏览器提供翻译能力）</td></tr><tr><td>复制内容 / 复制链接</td><td>复制正文或帖子地址</td></tr><tr><td>嵌入</td><td>生成可嵌入其他网页的代码</td></tr><tr><td>静音帖文串</td><td>不再接收该帖子串的回复通知</td></tr><tr><td>置顶</td><td>仅自己的帖子，置顶到个人主页，数量上限由服务器策略决定</td></tr><tr><td>删除并编辑</td><td>仅自己的帖子，删除原帖并把内容带回发帖框重新编辑（原帖的回应、转帖会丢失）</td></tr><tr><td>删除</td><td>仅自己的帖子</td></tr></tbody></table><h2 id="搜索" tabindex="-1">搜索 <a class="header-anchor" href="#搜索" aria-label="Permalink to &quot;搜索&quot;">​</a></h2><p>侧栏「搜索」分「帖子」「用户」两个标签。</p><ul><li><strong>帖子</strong>：按关键词搜索，可在选项中限定范围为「全部」或「指定用户」。</li><li><strong>用户</strong>：按用户名或昵称搜索。</li><li>输入 <code>#标签</code> 会跳转到对应话题标签页。</li></ul><p><img src="'+d+'" alt="搜索"></p><h2 id="个人主页" tabindex="-1">个人主页 <a class="header-anchor" href="#个人主页" aria-label="Permalink to &quot;个人主页&quot;">​</a></h2><p>点击头像进入用户主页，顶部标签依次为：概览、帖子、文件、活动、成就、回应、便签、列表、页面、Play、图集。</p><ul><li>概览页显示简介、附加信息、注册时间、帖子数、关注与关注者，以及置顶的帖子。</li><li>「回应」标签只在对方开启「将回应设置为公开」时显示内容。</li><li>「…」菜单可发私信、搜索该用户的帖子、开启新帖通知、加入列表或天线、隐藏（可选时长）、隐藏转帖、屏蔽、举报，以及显示二维码；「添加备注」可写仅自己可见的备注。</li></ul><p><img src="'+n+'" alt="个人主页"></p><h2 id="关注与关注请求" tabindex="-1">关注与关注请求 <a class="header-anchor" href="#关注与关注请求" aria-label="Permalink to &quot;关注与关注请求&quot;">​</a></h2><ul><li>对方开启了「关注请求需要批准」时，关注会变成发送关注请求，对方同意后才生效。</li><li>侧栏「关注请求」分「收到的请求」「发送的请求」两个标签，在此同意、拒绝或撤回。</li></ul><h2 id="公告" tabindex="-1">公告 <a class="header-anchor" href="#公告" aria-label="Permalink to &quot;公告&quot;">​</a></h2><p>侧栏「公告」展示服务器发布的公告，分「现在的公告」和「过去的公告」。有未读公告时会弹出提示，部分公告需要点击「我知道了」确认后才会消失。<a href="/guide/rules">社区规范</a>也以公告形式发布。</p>',37)])])}const k=r(p,[["render",h]]);export{f as __pageData,k as default};
